/**
 * @summary List project lifecycle requests. Admins see pending requests in
their org scope; other signed-in users see only their own
requests (every status).

 */
export const getListProjectLifecycleRequestsUrl = (
  params?: ListProjectLifecycleRequestsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/projects/lifecycle-requests?${stringifiedParams}`
    : `/api/projects/lifecycle-requests`;
};

