/**
 * Returns up to 100 most recent in-app access requests submitted
from the SSO deny banner, newest first. By default only pending
rows are returned; pass `includeResolved=true` to include rows
an admin has already marked handled.

 * @summary List in-app "Request access" submissions (admin only)
 */
export const getListSsoAccessRequestsUrl = (
  params?: ListSsoAccessRequestsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/sso-access-requests?${stringifiedParams}`
    : `/api/sso-access-requests`;
};

export const listSsoAccessRequests = async (
  params?: ListSsoAccessRequestsParams,
  options?: RequestInit,
): Promise<SsoAccessRequest[]> => {
  return customFetch<SsoAccessRequest[]>(getListSsoAccessRequestsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListSsoAccessRequestsQueryKey = (
  params?: ListSsoAccessRequestsParams,
) => {
  return [`/api/sso-access-requests`, ...(params ? [params] : [])] as const;
};

