/**
 * Returns up to 50 most recent SSO sign-ins that were rejected by
the identity provider claim gates (`mementoUser` user-gate and
`mementoAccess` org-gate). Rows older than 30 days are pruned
lazily on each call. Used by Admin → Source control → SSO
denials so an admin can confirm a denied user attempted a
sign-in and respond.

By default, denials an admin has marked handled are hidden so
the queue only shows actionable rows. Pass `includeHandled=true`
to surface dismissed denials too (used by the "Show handled"
toggle in the admin UI).

 * @summary List recent SSO sign-in denials (admin only)
 */
export const getListSsoDenialsUrl = (params?: ListSsoDenialsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/sso-denials?${stringifiedParams}`
    : `/api/sso-denials`;
};

